test("bulk void scenario 3", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-20");
  await ui.setSetting(pg_uma, "clerk-limit", "3.00");
  await ui.setSetting(pg_uma, "floor", "2.00");
  await ui.setSetting(pg_uma, "terms", "10");
  await ui.setSetting(pg_uma, "late-pct", "10.00");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  await ui.setSetting(pg_uma, "cap", "2.00");
  await ui.setSetting(pg_uma, "proof-threshold", "3.00");
  await ui.setSetting(pg_uma, "note-threshold", "1.00");
  expect(await ui.addVoidReason(pg_uma, "dup")).toBe(true);
  await ui.loadSheet(pg_uma, `${sheet}-p`);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "7.50"})).toBe(true);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B"}));
  const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "0.04"}));
  expect(await ui.claimAction(pg_uma, c_cam_0, "open")).toBe(true);
  await ui.loadSheet(pg_uma, sheet);
  await ui.setSetting(pg_uma, "parent", `${sheet}-p`);
  expect(await ui.saveTemplate(pg_uma, {"name": "T1", "amount": "12.50", "note": "tpl"})).toBe(true);
  await ui.setSetting(pg_uma, "review-sla", "5");
  await ui.setSetting(pg_uma, "default-grade", "A");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00", "from": "2026-03-10"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
  expect(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C"})).toBeNull();
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A", "terms": "20"}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A", "terms": "20"}));
  expect(await ui.addPool(pg_uma, "P1")).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ada", "share": "70.00"})).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ben", "share": "20.00"})).toBe(true);
  expect(await ui.editPerson(pg_uma, p_ada, {"terms": "3", "termsFrom": "2026-03-01"})).toBe(true);
  const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "25.00", "note": "n", "tags": "a, B"}));
  expect(await ui.addAlias(pg_uma, p_ben, "Bee")).toBe(true);
  const c_ben_0 = ui.must(await ui.claimFromTemplate(pg_uma, p_ben, "T1"));
  expect(await ui.editPerson(pg_uma, p_ada, {"terms": ""}, {"terms": "3"})).toBe(true);
  expect(await ui.retire(pg_uma, p_ada, "2026-03-05")).toBe(true);
    `SETTING_CHANGED sheet=${sheet} by=uma key=proof-threshold value=3.00`,
    `SETTING_CHANGED sheet=${sheet} by=uma key=note-threshold value=1.00`,
    `VOID_REASON_ADDED sheet=${sheet} by=uma reason=dup`,
    `SETTING_CHANGED sheet=${sheet} by=uma key=parent value=${sheet}-p`,
    `TEMPLATE_SAVED sheet=${sheet} by=uma name=T1 amount=12.50 note=tpl`,
    `SETTING_CHANGED sheet=${sheet} by=uma key=review-sla value=5`,
    `SETTING_CHANGED sheet=${sheet} by=uma key=default-grade value=A`,
    `RATE_SET sheet=${sheet} by=uma grade=A rate=12.50`,
    `RATE_SET sheet=${sheet} by=uma grade=B rate=20.00`,
    `RATE_SET sheet=${sheet} by=uma grade=C rate=5.00`,
    `RATE_SET sheet=${sheet} by=uma grade=B rate=20.00 from=2026-03-10`,
    `PERIOD_ADDED sheet=${sheet} by=uma period=P1 from=2026-03-01 to=2026-03-15`,
    `PERIOD_ADDED sheet=${sheet} by=uma period=P2 from=2026-03-16 to=2026-03-31`,
    `PERSON_ADDED sheet=${sheet} by=uma name=Ada grade=A terms=20`,
    `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=0.00 overdue-total=0.00`,
    `PERSON_ADDED sheet=${sheet} by=uma name=Ben grade=A terms=20`,
    `ROLLUP sheet=${sheet} by=uma person=Ben claimed=0.00 due-total=0.00 overdue-total=0.00`,
    `POOL_ADDED sheet=${sheet} by=uma name=P1`,
    `POOL_MEMBER_ADDED sheet=${sheet} by=uma pool=P1 name=Ada share=70.00`,
    `POOL_MEMBER_ADDED sheet=${sheet} by=uma pool=P1 name=Ben share=20.00`,
    `PERSON_EDITED sheet=${sheet} by=uma name=Ada grade=A terms=3`,
    `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=25.00 date=2026-03-20 tags=a,b`,
    `PERSON_ALIAS_ADDED sheet=${sheet} by=uma name=Ben alias=Bee`,
    `CLAIM_ADDED sheet=${sheet} by=uma person=Ben amount=12.50 date=2026-03-20`,
    `PERSON_EDITED sheet=${sheet} by=uma name=Ada grade=A terms=3`,
    `PERSON_RETIRED sheet=${sheet} by=uma name=Ada from=2026-03-05`,
              person.getTags().isEmpty() ? null : String.join(",", person.getTags()));
  }

  /** Saves the person as {@link #update(String, String, long, long, String, String, LocalDate, Integer,
   * String)} does, giving them the tags {@code tags} (see {@link Claim#tagsOf}; none when null). */
  @Transactional
  public Person update(String sheetId, String user, long personId, long version, String name, String grade,
          LocalDate gradeFrom, Integer terms, String contact, String tags) {
      return update(sheetId, user, personId, version, name, grade, gradeFrom, terms, null, contact, tags);
  }

  /** Saves the person as {@link #update(String, String, long, long, String, String, LocalDate, Integer,
   * String, String)} does, but with {@code terms} (none when null) given from {@code termsFrom}, in place
   * of those given from the same date and keeping those given from other dates; from the beginning of
   * time when {@code termsFrom} is null. */
  @Transactional
  public Person update(String sheetId, String user, long personId, long version, String name, String grade,
          LocalDate gradeFrom, Integer terms, LocalDate termsFrom, String contact, String tags) {
      Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
      if (person.getVersion() != version) {
          throw new PersonStaleException(person);
      }
      requireFree(sheetId, name, person.getId());
      tree.requireFree(sheetId, name);
      person.getAliases().forEach(alias -> tree.requireFree(sheetId, alias));
      requireContactFree(sheetId, contact, person.getId());
      RollupService.Snapshot before = rollup.snapshot(sheetId);
      LocalDate today = sheetService.today(sheetId);
      person.setName(name);
      // A grade left as it is today, with no from-date, adds no dated grade.
      if (gradeFrom != null || !Objects.equals(grade, person.gradeOn(today))) {
          person.setGrade(grade, gradeFrom != null ? gradeFrom : today);
      }
      // The terms are recorded when the save moves the terms shown, those in force today.
      Integer termsBefore = person.termsOn(today);
      if (termsFrom == null) {
          person.setTerms(terms);
      } else {
          person.setTerms(terms, termsFrom);
      }
      boolean termsChanged = !Objects.equals(termsBefore, person.termsOn(today));
      boolean contactChanged = !Objects.equals(person.getContact(), Person.contactOf(contact));
      person.setContact(contact);
      person.setTags(tags);
      people.flush();
      keepTags(person);
      List<String> fields = new ArrayList<>(List.of("name=" + person.getName(), "grade=" + person.gradeOn(today)));
      Integer termsToday = person.termsOn(today);
      if (termsChanged) fields.add("terms=" + (termsToday == null ? "" : termsToday));
      if (contactChanged) fields.add("contact=" + (person.getContact() == null ? "" : person.getContact()));
      audit.change("PERSON_EDITED", sheetId, user, fields.toArray(String[]::new));

